#!/usr/bin/env python3
"""Build the editable C project, replay frames, and serialize certificates."""
import ctypes as C,hashlib,json,os,struct,subprocess,sys,tempfile
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
from wire import NAMES,emissions
from request import load

def run(case,lib):
    tape=hashlib.sha256();accepted=0;wire_bytes=0;budget=-1;trace=[];snaps=[]
    limit=case.get('trace',0)
    CALLBACK=C.CFUNCTYPE(C.c_int,C.c_void_p,C.c_int,C.POINTER(C.c_uint8),C.c_size_t)
    def emit(user,rank,pointer,length):
        nonlocal accepted,wire_bytes,budget
        if budget==0:return 0
        if budget>0:budget-=1
        frame=C.string_at(pointer,length)
        tape.update(bytes((rank,))+struct.pack('<I',length)+frame)
        accepted+=1;wire_bytes+=length
        if len(trace)<limit:trace.append({'rank':rank,'hex':frame.hex()})
        return 1
    callback=CALLBACK(emit)
    lib.epic_open.argtypes=[C.c_int]*3+[C.c_uint32]*4+[CALLBACK,C.c_void_p];lib.epic_open.restype=C.c_void_p
    lib.epic_ingress.argtypes=[C.c_void_p,C.c_int,C.c_char_p,C.c_size_t]
    lib.epic_flush.argtypes=[C.c_void_p];lib.epic_retry.argtypes=[C.c_void_p,C.c_int]
    lib.epic_close.argtypes=[C.c_void_p];lib.epic_state.argtypes=[C.c_void_p,C.POINTER(C.c_uint64)]
    lib.epic_digest.argtypes=[C.c_void_p];lib.epic_digest.restype=C.c_uint64
    context=lib.epic_open(NAMES.index(case['primitive']),case['mode'],case['root'],case['segments'],case['words'],case['capacity'],case['start'],callback,None)
    if not context:raise RuntimeError('allocation failed')
    def snapshot():
        state=(C.c_uint64*32)();lib.epic_state(context,state)
        return {'state':list(state),'buffer':format(lib.epic_digest(context),'016x'),'wire_sha256':tape.hexdigest(),'packets':accepted,'bytes':wire_bytes}
    try:
        for name,arg,frame in emissions(case):
            if name=='wire':lib.epic_ingress(context,arg,frame,len(frame))
            elif name=='flush':lib.epic_flush(context)
            elif name=='retry':lib.epic_retry(context,arg)
            elif name=='budget':budget=arg
            elif name=='snap':snaps.append({'tag':arg,**snapshot()})
            else:raise ValueError('unknown operation')
        return {**snapshot(),'snapshots':snaps,'trace':trace}
    finally:lib.epic_close(context)

def solve(request):
    if not request['cases']:return {'cases':[]}
    here=Path(__file__).resolve().parent
    scratch=Path(os.environ.get('TMPDIR','/tmp'))
    with tempfile.TemporaryDirectory(prefix='epic-build-',dir=scratch) as build:
        p=subprocess.run(['make','-s','-C',str(here),'BUILD='+build,'-j2'],stdout=subprocess.PIPE,stderr=subprocess.PIPE)
        if p.returncode:raise RuntimeError(p.stderr.decode(errors='replace'))
        lib=C.CDLL(str(Path(build)/'libepic.so'))
        return {'cases':[run(case,lib) for case in request['cases']]}

if __name__=='__main__':
    try:
        request=load(sys.stdin.buffer.read(4*1024**2+1))
    except (ValueError,TypeError,KeyError,UnicodeError,RecursionError,OverflowError):
        response={'error':'invalid'}
    else:response=solve(request)
    print(json.dumps(response,separators=(',',':'),allow_nan=False))

"""Wire-format utilities only; no collective state machine."""
import struct,zlib
MASK=(1<<24)-1
NAMES=('allreduce','reduce','broadcast','barrier','allgather','reducescatter')
def checksum(data):
    total=sum(struct.unpack('!10H',data))
    while total>>16:total=(total&65535)+(total>>16)
    return (~total)&65535

def seal(frame):
    frame=bytearray(frame)
    frame[24:26]=b'\0\0';frame[24:26]=struct.pack('!H',checksum(frame[14:34]))
    crc=bytearray(b'\xff'*8+frame[14:-4])
    crc[9]=255;crc[16]=255;crc[18:20]=b'\xff\xff';crc[34:36]=b'\xff\xff';crc[40]=255
    frame[-4:]=struct.pack('<I',zlib.crc32(crc))
    return bytes(frame)

def packet(rank,physical,payload=b'',ack=False,outgoing=False):
    hostmac=bytes((2,0,0,0,0,rank+1));swmac=bytes((2,1,0,0,0,rank+1))
    hostip=bytes((10,0,0,rank+1));swip=bytes((10,0,0,101+rank))
    sm,dm,si,di,q=(swmac,hostmac,swip,hostip,0x100+rank) if outgoing else (hostmac,swmac,hostip,swip,0x200+rank)
    body=struct.pack('!I',0x1f000000|((physical+1)&MASK)) if ack else payload
    bth=struct.pack('!BBHII',0x11 if ack else 4,0,65535,q,(physical&MASK)|(0 if ack else 0x80000000))
    udp=struct.pack('!HHHH',4791,4791,8+12+len(body)+4,0)
    ip=struct.pack('!BBHHHBBH4s4s',0x45,0,20+len(udp)+len(bth)+len(body)+4,0x1111,0x4000,64,17,0,si,di)
    return seal(dm+sm+b'\x08\x00'+ip+udp+bth+body+b'\0'*4)

def payload(seed,p,rank,words):
    return struct.pack('!%dI'%words,*((seed+0x9e3779b9*(p+1)+0x85ebca6b*(rank+1)+0xc2b2ae35*(j+1))&0xffffffff for j in range(words)))

def emissions(case):
    """Expand public input shorthand; performs no simulated switch decisions."""
    base=case['start'];kind=case['primitive'];k=case['segments'];d=case['words']
    for op in case['events']:
        name=op['op']
        if name=='data':
            r=op['rank']
            for i in range(op.get('count',1)):
                p=op['p']+i*op.get('step',1)
                body=struct.pack('!%dI'%len(op['values']),*op['values']) if 'values' in op else payload(op.get('seed',0),p,r,d)
                f=bytearray(packet(r,(base+p)&MASK,body))
                for offset,value in op.get('xor',[]):f[offset]^=value
                yield ('wire',r,bytes(f))
        elif name=='ack':yield ('wire',op['rank'],packet(op['rank'],(base+op['upto']-1)&MASK,ack=True))
        elif name=='wire':yield ('wire',op['rank'],bytes.fromhex(op['hex']))
        elif name=='train':
            end=op['p']+op['count']
            for lo in range(op['p'],end,op['width']):
                hi=min(end,lo+op['width'])
                for r in op['ranks']:
                    if kind=='broadcast' and r!=case['root']:continue
                    seq=range(hi-1,lo-1,-1) if op.get('reverse',False) else range(lo,hi)
                    for p in seq:yield ('wire',r,packet(r,(base+p)&MASK,payload(op.get('seed',0),p,r,d)))
                for r in range(4):
                    n=3*hi if kind=='allgather' else max(0,min(k//4,hi-r*(k//4))) if kind=='reducescatter' else hi if (kind!='reduce' or r==case['root']) and (kind!='broadcast' or r!=case['root']) else 0
                    yield ('wire',r,packet(r,(base+n-1)&MASK,ack=True))
        else:yield (name,op.get('rank',op.get('n',op.get('tag'))),None)
