"""Public request schema and expansion accounting, without collector semantics."""
import json
MAX_INPUT=4*1024**2
MAX_WORK=2**20
MAX_TRAFFIC=256*1024**2
PRIMITIVES=('allreduce','reduce','broadcast','barrier','allgather','reducescatter')
def integer(x,lo,hi):return type(x) is int and lo<=x<=hi
def shape(x,required,optional=()):
    return type(x) is dict and set(required)<=x.keys() and x.keys()<=set(required)|set(optional)
def need(condition):
    if not condition:raise ValueError('invalid request')
def load(raw):
    need(len(raw)<=MAX_INPUT)
    def pairs(items):
        d={}
        for k,v in items:
            need(k not in d);d[k]=v
        return d
    def bad(_):raise ValueError('nonfinite number')
    value=json.loads(raw.decode('utf-8'),object_pairs_hook=pairs,parse_constant=bad)
    validate(value)
    return value

def validate(request):
    need(shape(request,['cases']) and type(request['cases']) is list and len(request['cases'])<=8)
    work=traffic=events=0
    for c in request['cases']:
        need(shape(c,['primitive','mode','root','segments','words','capacity','start','events'],['trace']))
        kind=c['primitive'];K=c['segments'];D=c['words'];N=c['capacity']
        need(type(kind) is str and kind in PRIMITIVES)
        need(integer(c['mode'],2,3) and integer(c['root'],0,3))
        need(integer(K,1,2**20) and integer(N,1,4096) and integer(c['start'],0,2**24-1))
        need(integer(D,0,1024) and ((kind=='barrier' and D==0 and K==1) or (kind!='barrier' and D>=1)))
        need(kind!='reducescatter' or K%4==0)
        need(integer(c.get('trace',0),0,32) and type(c['events']) is list)
        events+=len(c['events']);need(events<=65536)
        for op in c['events']:
            need(type(op) is dict and type(op.get('op')) is str)
            name=op['op']
            if name=='data':
                need(shape(op,['op','rank','p'],['count','step','seed','values','xor']))
                count=op.get('count',1);step=op.get('step',1);p=op['p']
                need(integer(op['rank'],0,3) and integer(p,0,K-1) and integer(count,1,2**20))
                need(integer(step,-2**20,2**20) and 0<=p+(count-1)*step<K)
                need(integer(op.get('seed',0),0,2**32-1))
                if 'values' in op:
                    need(count==1 and type(op['values']) is list and len(op['values'])==D and all(integer(v,0,2**32-1) for v in op['values']))
                edits=op.get('xor',[]);need(type(edits) is list)
                for pair in edits:need(type(pair) is list and len(pair)==2 and integer(pair[0],0,57+4*D) and integer(pair[1],0,255))
                work+=count*(1+len(edits));traffic+=4*count*(58+4*D)
            elif name=='ack':
                need(shape(op,['op','rank','upto']) and integer(op['rank'],0,3) and integer(op['upto'],0,3*K+1))
                work+=1;traffic+=4*62
            elif name=='wire':
                need(shape(op,['op','rank','hex']) and integer(op['rank'],0,3))
                h=op['hex'];need(type(h) is str and len(h)<=8308 and len(h)%2==0 and all(x in '0123456789abcdefABCDEF' for x in h))
                work+=1;traffic+=4*(len(h)//2)
            elif name=='budget':
                need(shape(op,['op','n']) and integer(op['n'],-1,2**31-1));work+=1
            elif name=='flush':
                need(shape(op,['op']));work+=1
            elif name=='retry':
                need(shape(op,['op','rank']) and integer(op['rank'],0,3));work+=12*N+4;traffic+=(12*N+4)*(4*D+62)
            elif name=='snap':
                need(shape(op,['op','tag']) and type(op['tag']) is str and len(op['tag'].encode('utf-8'))<=64)
                work+=N;traffic+=N*(16*D+32)
            elif name=='train':
                need(shape(op,['op','p','count','width','ranks'],['reverse','seed']))
                need(integer(op['p'],0,K-1) and integer(op['count'],1,2**20) and op['p']+op['count']<=K and integer(op['width'],1,N))
                ranks=op['ranks'];need(type(ranks) is list and len(ranks)==4 and all(integer(r,0,3) for r in ranks) and sorted(ranks)==[0,1,2,3])
                need(type(op.get('reverse',False)) is bool and integer(op.get('seed',0),0,2**32-1))
                data=op['count']*(1 if kind=='broadcast' else 4);acks=4*((op['count']+op['width']-1)//op['width'])
                work+=data+acks;traffic+=4*(data*(58+4*D)+acks*62)
            else:raise ValueError('unknown operation')
            need(work<=MAX_WORK and traffic<=MAX_TRAFFIC)
    return {'work':work,'traffic':traffic,'events':events}

#include "star4_switch.c"

void *epic_open(int primitive,int mode,int root,uint32_t count,uint32_t words,
                uint32_t capacity,uint32_t start,epic_emit_fn emit,void *user) {
    switch_ctx_t *ctx=calloc(1,sizeof(*ctx));
    if(!ctx)return NULL;
    ctx->capacity=capacity;ctx->input_count=count;ctx->base24=start;
    ctx->slots=calloc(capacity,sizeof(slot_state_t));
    if(!ctx->slots){free(ctx);return NULL;}
    ctx->cfg.primitive=(epic_primitive_t)primitive;ctx->cfg.mode=(epic_mode_t)mode;
    ctx->cfg.root_rank=root;ctx->cfg.payload_bytes=(int)words*4;
    ctx->cfg.count=(int)(count*words*(primitive==EPIC_PRIM_ALLGATHER?4:1));
    for(int r=0;r<4;r++) {
        epic_port_t *p=&ctx->cfg.ports[r];p->rank=r;
        p->host_mac[0]=2;p->host_mac[5]=(uint8_t)(r+1);
        p->switch_mac[0]=2;p->switch_mac[1]=1;p->switch_mac[5]=(uint8_t)(r+1);
        p->host_ip=htonl(0x0a000001u+(uint32_t)r);
        p->switch_ip=htonl(0x0a000065u+(uint32_t)r);
        p->host_qpn=0x100u+(uint32_t)r;p->switch_qpn=0x200u+(uint32_t)r;
        ctx->handles[r]=calloc(1,sizeof(pcap_t));
        if(!ctx->handles[r])abort();
        *ctx->handles[r]=(pcap_t){.user=user,.rank=r,.emit=emit};
    }
    return ctx;
}
void epic_close(void *context) {
    switch_ctx_t *ctx=context;if(!ctx)return;
    for(uint32_t i=0;i<ctx->capacity;i++)cleanup_slot(&ctx->slots[i]);
    for(int r=0;r<4;r++)free(ctx->handles[r]);
    free(ctx->slots);free(ctx);
}
int epic_ingress(void *context,int rank,const uint8_t *frame,size_t length) {
    return handle_packet(context,rank,frame,length);
}
int epic_flush(void *context) {return drain_ordered_results(context);}
int epic_retry(void *context,int rank) {(void)rank;return epic_flush(context);}
void epic_state(void *context,uint64_t *state) {
    switch_ctx_t *ctx=context;memset(state,0,32*sizeof(*state));state[0]=ctx->retired;
    for(uint32_t i=0;i<ctx->capacity;i++)state[1]+=ctx->slots[i].in_use;
    for(int r=0;r<4;r++) {state[2+r]=ctx->rx_next[r];state[6+r]=ctx->sent_next[r];state[10+r]=ctx->ack_next[r];state[14+r]=ctx->up_sent[r];}
    uint64_t values[]={ctx->rx_data,ctx->rx_ack,ctx->tx_data,ctx->tx_ack,ctx->accepted,
      ctx->duplicates,ctx->blocked,ctx->stale,ctx->invalid_wire,ctx->invalid_endpoint,
      ctx->ack_ignored,ctx->failed_sends,ctx->slot_overwrites};
    memcpy(state+18,values,sizeof(values));
}
static uint64_t fold_byte(uint64_t hash,uint8_t value){return (hash^value)*UINT64_C(1099511628211);}
static uint64_t fold_u64(uint64_t hash,uint64_t value){for(int j=0;j<8;j++){hash=fold_byte(hash,(uint8_t)value);value>>=8;}return hash;}
uint64_t epic_digest(void *context) {
    switch_ctx_t *ctx=context;uint64_t h=UINT64_C(14695981039346656037);
    for(uint32_t p=ctx->retired;p<ctx->input_count && p-ctx->retired<ctx->capacity;p++) {
        slot_state_t *slot=&ctx->slots[slot_idx(ctx,p)];
        if(!slot->in_use || slot->psn!=p)continue;
        h=fold_u64(h,p);h=fold_byte(h,slot->data_mask);h=fold_byte(h,slot->result_ready);
        if(ctx->cfg.primitive==EPIC_PRIM_ALLGATHER) {
            for(int r=0;r<4;r++) {
                h=fold_byte(h,slot->allgather_raw[r]!=NULL);
                if(slot->allgather_raw[r])for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->allgather_raw[r][j]);
            }
        } else if(ctx->cfg.primitive==EPIC_PRIM_BCAST) {
            for(int j=0;j<ctx->cfg.payload_bytes;j++)h=fold_byte(h,slot->data.bcast_raw[j]);
        } else {
            for(int j=0;j<ctx->cfg.payload_bytes/4;j++) {
                uint32_t value;memcpy(&value,&slot->data.accum[j],4);
                for(int k=0;k<4;k++){h=fold_byte(h,(uint8_t)value);value>>=8;}
            }
        }
    }
    return h;
}

