/* Offline four-port collective collector.
 *
 * Strict implementation of the PROTOCOL.md replay contract: finite CPU packet
 * replay with wire/endpoint validation, bounded retention, cumulative ACKs,
 * transport backpressure and canonical egress construction. All state is
 * in-memory; nothing here touches live I/O.
 */
#define _DEFAULT_SOURCE

#include "epic_clean.h"
#include "offline_api.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define ALLMASK 0x0fu
#define MAX_WORDS (EPIC_MAX_PAYLOAD_BYTES / 4)
#define MAX_FRAME (14 + 20 + 8 + 12 + EPIC_MAX_PAYLOAD_BYTES + 4)

/* ------------------------------------------------------------------ */
/* State                                                               */
/* ------------------------------------------------------------------ */

typedef struct {
    bool in_use;
    uint32_t p;                /* logical input sequence of this slot */
    uint8_t mask;              /* accepted source bitmask */
    uint32_t agg[MAX_WORDS];   /* running sum for aggregate primitives */
    uint8_t *raw[4];           /* raw vectors: gather per source, bcast root */
} slot_t;

typedef struct {
    int prim, mode, root;
    uint32_t K, D, N, start;
    size_t paylen;             /* 4*D */
    slot_t *slots;             /* N entries, indexed by logical p mod N */
    uint64_t b;                /* retired prefix */
    uint64_t occ;              /* occupied slot count */
    uint64_t R[4], E[4], U[4], sent[4], ackd[4];
    bool repeat[4];
    uint64_t rx_data, rx_ack, tx_data, tx_ack;
    uint64_t accepted, duplicates, blocked, stale;
    uint64_t invalid_wire, invalid_endpoint, ack_ignored, failed_sends;
    uint64_t slot_overwrites;
    epic_emit_fn emit;
    void *user;
} coll_t;

/* ------------------------------------------------------------------ */
/* Small helpers                                                       */
/* ------------------------------------------------------------------ */

static uint16_t be16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | p[1]);
}
static uint32_t be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}
static uint32_t le32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static int ordinal_excluding(int d, int s) {
    int o = 0;
    for (int r = 0; r < 4; r++) {
        if (r == d) continue;
        if (r == s) return o;
        o++;
    }
    return -1;
}
static int rank_from_ordinal(int d, int o) {
    for (int r = 0; r < 4; r++) {
        if (r == d) continue;
        if (o-- == 0) return r;
    }
    return -1;
}

static uint8_t required_mask(const coll_t *c) {
    return (uint8_t)(c->prim == EPIC_PRIM_BCAST ? (1u << c->root) : ALLMASK);
}

static slot_t *slot_at(const coll_t *c, uint64_t p) {
    slot_t *s = &c->slots[p % c->N];
    return (s->in_use && s->p == (uint32_t)p) ? s : NULL;
}

static void clear_slot(coll_t *c, slot_t *s) {
    (void)c;
    for (int r = 0; r < 4; r++) {
        free(s->raw[r]);
        s->raw[r] = NULL;
    }
    memset(s, 0, sizeof(*s));
}

static bool slot_complete(const coll_t *c, const slot_t *s) {
    return (s->mask & required_mask(c)) == required_mask(c);
}

/* ------------------------------------------------------------------ */
/* CRC32 (reflected, poly 0xedb88320) and ICRC                          */
/* ------------------------------------------------------------------ */

static uint32_t crc_table[256];
static bool crc_ready;

static void crc_init(void) {
    if (crc_ready) return;
    for (uint32_t i = 0; i < 256; i++) {
        uint32_t v = i;
        for (int j = 0; j < 8; j++) v = (v >> 1) ^ ((v & 1u) ? 0xedb88320u : 0u);
        crc_table[i] = v;
    }
    crc_ready = true;
}

static uint32_t crc32_refl(const uint8_t *data, size_t len) {
    crc_init();
    uint32_t crc = 0xffffffffu;
    for (size_t i = 0; i < len; i++)
        crc = (crc >> 8) ^ crc_table[(crc ^ data[i]) & 0xffu];
    return crc ^ 0xffffffffu;
}

/* ICRC input: 8 x 0xff then the IPv4 datagram minus ICRC with TOS, TTL,
 * IPv4 checksum, UDP checksum and QPN top byte masked to 0xff. */
static uint32_t compute_icrc(const uint8_t *frame, size_t ip_total) {
    uint8_t buf[8 + 20 + 8 + 12 + EPIC_MAX_PAYLOAD_BYTES];
    size_t crc_len = 8 + ip_total - 4;
    if (ip_total < 44 || crc_len > sizeof(buf)) return 0;
    memset(buf, 0xff, 8);
    memcpy(buf + 8, frame + 14, ip_total - 4);
    buf[8 + 1] = 0xff;                 /* TOS */
    buf[8 + 8] = 0xff;                 /* TTL */
    buf[8 + 10] = buf[8 + 11] = 0xff;  /* IPv4 checksum */
    buf[8 + 20 + 6] = buf[8 + 20 + 7] = 0xff; /* UDP checksum */
    buf[8 + 20 + 8 + 4] = 0xff;        /* QPN top byte */
    return crc32_refl(buf, crc_len);
}

static bool ip_checksum_ok(const uint8_t *h) {
    uint32_t sum = 0;
    for (int i = 0; i < 20; i += 2) sum += be16(h + i);
    while (sum >> 16) sum = (sum & 0xffffu) + (sum >> 16);
    return sum == 0xffffu;
}

/* ------------------------------------------------------------------ */
/* Ingress validation                                                  */
/* ------------------------------------------------------------------ */

typedef struct {
    bool is_ack;
    uint32_t psn;              /* 24-bit wire PSN */
    const uint8_t *payload;    /* DATA payload (4D bytes) */
} parsed_t;

static bool wire_valid(const coll_t *c, const uint8_t *f, size_t len,
                       parsed_t *out) {
    if (len < 14 + 20 + 8 + 12 + 4) return false;
    if (be16(f + 12) != 0x0800) return false;          /* EtherType IPv4 */
    if (f[14] != 0x45) return false;                   /* version/IHL */
    if (f[23] != 17) return false;                     /* UDP protocol */
    uint16_t flags = be16(f + 20);
    if (flags != 0x0000 && flags != 0x4000) return false;
    if (!ip_checksum_ok(f + 14)) return false;
    uint32_t ip_total = be16(f + 16);
    if (len != (size_t)ip_total + 14) return false;
    if (ip_total < 44) return false;
    if (be16(f + 34) != 4791 || be16(f + 36) != 4791) return false;
    if (be16(f + 38) != ip_total - 20) return false;
    if (be16(f + 40) != 0) return false;
    uint8_t opcode = f[42];
    if (opcode != 0x04 && opcode != 0x11) return false;
    if (f[43] != 0) return false;
    if (be16(f + 44) != 0xffff) return false;
    uint32_t qpn = be32(f + 46);
    if ((qpn >> 24) != 0) return false;
    uint32_t apsn = be32(f + 50);
    uint32_t psn = apsn & 0x00ffffffu;
    if (opcode == 0x04) {
        if ((apsn >> 24) != 0x80) return false;
        if (ip_total != 44 + 4u * c->D) return false;
        out->is_ack = false;
        out->psn = psn;
        out->payload = f + 54;
    } else {
        if ((apsn >> 24) != 0x00) return false;
        if (ip_total != 48) return false;
        if (f[54] != 0x1f) return false;
        if ((be32(f + 54) & 0x00ffffffu) != ((psn + 1) & 0x00ffffffu))
            return false;
        out->is_ack = true;
        out->psn = psn;
        out->payload = NULL;
    }
    if (le32(f + len - 4) != compute_icrc(f, ip_total)) return false;
    return true;
}

static bool endpoint_ok(const coll_t *c, int rank, const uint8_t *f,
                        const parsed_t *in) {
    const uint8_t hostmac[6] = {2, 0, 0, 0, 0, (uint8_t)(rank + 1)};
    const uint8_t swmac[6] = {2, 1, 0, 0, 0, (uint8_t)(rank + 1)};
    if (memcmp(f, swmac, 6) != 0) return false;       /* dst = switch MAC */
    if (memcmp(f + 6, hostmac, 6) != 0) return false; /* src = host MAC */
    uint32_t hostip = 0x0a000001u + (uint32_t)rank;
    uint32_t swip = 0x0a000065u + (uint32_t)rank;
    if (be32(f + 26) != hostip) return false;         /* src = host IP */
    if (be32(f + 30) != swip) return false;           /* dst = switch IP */
    if ((be32(f + 46) & 0x00ffffffu) != (uint32_t)(0x200 + rank))
        return false;
    if (!in->is_ack) {
        /* DATA needs a required source and logical p in [0,K). */
        if (c->prim == EPIC_PRIM_BCAST && rank != c->root) return false;
        uint32_t p = (in->psn - c->start) & 0x00ffffffu;
        if (p >= c->K) return false;
    }
    return true;
}

/* ------------------------------------------------------------------ */
/* Output space mapping                                                */
/* ------------------------------------------------------------------ */

static uint64_t out_len(const coll_t *c, int d) {
    switch (c->prim) {
    case EPIC_PRIM_ALLREDUCE: return c->K;
    case EPIC_PRIM_REDUCE: return d == c->root ? c->K : 0;
    case EPIC_PRIM_BCAST: return d == c->root ? 0 : c->K;
    case EPIC_PRIM_BARRIER: return 1;
    case EPIC_PRIM_ALLGATHER: return 3ull * c->K;
    case EPIC_PRIM_REDUCESCATTER: return c->K / 4;
    }
    return 0;
}

/* Map destination d's output sequence q to its input p (and gather source). */
static void out_map(const coll_t *c, int d, uint64_t q, uint32_t *p_out,
                    int *src_out) {
    uint32_t p;
    int src = -1;
    switch (c->prim) {
    case EPIC_PRIM_ALLGATHER:
        p = (uint32_t)(q / 3);
        src = rank_from_ordinal(d, (int)(q % 3));
        break;
    case EPIC_PRIM_REDUCESCATTER:
        p = (uint32_t)d * (c->K / 4) + (uint32_t)q;
        break;
    case EPIC_PRIM_BARRIER:
        p = 0;
        break;
    default:
        p = (uint32_t)q;
        break;
    }
    *p_out = p;
    *src_out = src;
}

/* ------------------------------------------------------------------ */
/* Safety / retirement predicates                                      */
/* ------------------------------------------------------------------ */

/* Mode 2: is contribution (r,p) covered by downstream acknowledgments? */
static bool safe2(const coll_t *c, int r, uint64_t p) {
    switch (c->prim) {
    case EPIC_PRIM_ALLREDUCE:
        return c->ackd[r] > p;
    case EPIC_PRIM_BARRIER:
        return c->ackd[r] > 0;
    case EPIC_PRIM_REDUCE:
        return c->ackd[c->root] > p;
    case EPIC_PRIM_BCAST:
        for (int d = 0; d < 4; d++)
            if (d != c->root && !(c->ackd[d] > p)) return false;
        return true;
    case EPIC_PRIM_REDUCESCATTER: {
        uint64_t blk = c->K / 4;
        return c->ackd[p / blk] > (p % blk);
    }
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < 4; d++) {
            if (d == r) continue;
            if (!(c->ackd[d] > 3 * p + (uint64_t)ordinal_excluding(d, r)))
                return false;
        }
        return true;
    }
    return true;
}

/* Are all required output records of input p acknowledged? */
static bool outs_acked(const coll_t *c, uint64_t p) {
    switch (c->prim) {
    case EPIC_PRIM_ALLREDUCE:
        for (int d = 0; d < 4; d++)
            if (!(c->ackd[d] > p)) return false;
        return true;
    case EPIC_PRIM_REDUCE:
        return c->ackd[c->root] > p;
    case EPIC_PRIM_BCAST:
        for (int d = 0; d < 4; d++)
            if (d != c->root && !(c->ackd[d] > p)) return false;
        return true;
    case EPIC_PRIM_BARRIER:
        for (int d = 0; d < 4; d++)
            if (!(c->ackd[d] > 0)) return false;
        return true;
    case EPIC_PRIM_ALLGATHER:
        for (int d = 0; d < 4; d++)
            if (!(c->ackd[d] > 3 * p + 2)) return false;
        return true;
    case EPIC_PRIM_REDUCESCATTER: {
        uint64_t blk = c->K / 4;
        return c->ackd[p / blk] > (p % blk);
    }
    }
    return true;
}

static bool retireable(const coll_t *c, uint64_t p) {
    const slot_t *s = slot_at(c, p);
    if (!s || !slot_complete(c, s)) return false;
    if (!outs_acked(c, p)) return false;
    uint8_t req = required_mask(c);
    for (int r = 0; r < 4; r++)
        if ((req & (1u << r)) && !(c->U[r] > p)) return false;
    return true;
}

static void retire(coll_t *c) {
    while (c->b < c->K && retireable(c, c->b)) {
        slot_t *s = slot_at(c, c->b);
        if (s) {
            clear_slot(c, s);
            c->occ--;
        }
        c->b++;
    }
}

static void refresh_E(coll_t *c) {
    for (int r = 0; r < 4; r++) {
        while (c->E[r] < c->R[r] &&
               (c->mode == EPIC_MODE_TERMINATION || safe2(c, r, c->E[r])))
            c->E[r]++;
    }
}

/* ------------------------------------------------------------------ */
/* Egress construction and service                                     */
/* ------------------------------------------------------------------ */

static bool do_emit(coll_t *c, int rank, const uint8_t *frame, size_t len) {
    if (c->emit(c->user, rank, frame, len) == 0) {
        c->failed_sends++;
        return false;
    }
    return true;
}

static bool send_up(coll_t *c, int r) {
    uint8_t frame[MAX_FRAME];
    const uint8_t swmac[6] = {2, 1, 0, 0, 0, (uint8_t)(r + 1)};
    const uint8_t hstmac[6] = {2, 0, 0, 0, 0, (uint8_t)(r + 1)};
    uint32_t swip = 0x0a000065u + (uint32_t)r;
    uint32_t hstip = 0x0a000001u + (uint32_t)r;
    uint32_t psn = (c->start + (uint32_t)c->E[r] - 1u) & 0x00ffffffu;
    size_t len = epic_build_roce_ack(frame, sizeof(frame), swmac, hstmac,
                                     swip, hstip, EPIC_ROCE_UDP_PORT,
                                     EPIC_ROCE_UDP_PORT,
                                     (uint32_t)(0x100 + r), psn);
    if (!len) return false;
    if (!do_emit(c, r, frame, len)) return false;
    c->tx_ack++;
    c->U[r] = c->E[r];
    c->repeat[r] = false;
    return true;
}

static bool send_result(coll_t *c, int d, uint64_t q) {
    uint8_t frame[MAX_FRAME];
    const uint8_t swmac[6] = {2, 1, 0, 0, 0, (uint8_t)(d + 1)};
    const uint8_t hstmac[6] = {2, 0, 0, 0, 0, (uint8_t)(d + 1)};
    uint32_t swip = 0x0a000065u + (uint32_t)d;
    uint32_t hstip = 0x0a000001u + (uint32_t)d;
    uint32_t psn = (c->start + (uint32_t)q) & 0x00ffffffu;
    uint32_t p;
    int src;
    out_map(c, d, q, &p, &src);
    slot_t *s = slot_at(c, p);
    if (!s) return false;
    size_t len;
    if (c->prim == EPIC_PRIM_BARRIER) {
        len = epic_build_roce_data(frame, sizeof(frame), swmac, hstmac, swip,
                                   hstip, EPIC_ROCE_UDP_PORT,
                                   EPIC_ROCE_UDP_PORT, (uint32_t)(0x100 + d),
                                   psn, NULL, 0);
    } else if (c->prim == EPIC_PRIM_BCAST || c->prim == EPIC_PRIM_ALLGATHER) {
        int sr = src >= 0 ? src : c->root;
        if (!s->raw[sr]) return false;
        len = epic_build_roce_data_raw(frame, sizeof(frame), swmac, hstmac,
                                       swip, hstip, EPIC_ROCE_UDP_PORT,
                                       EPIC_ROCE_UDP_PORT,
                                       (uint32_t)(0x100 + d), psn,
                                       s->raw[sr], c->paylen);
    } else {
        len = epic_build_roce_data(frame, sizeof(frame), swmac, hstmac, swip,
                                   hstip, EPIC_ROCE_UDP_PORT,
                                   EPIC_ROCE_UDP_PORT, (uint32_t)(0x100 + d),
                                   psn, (const int32_t *)s->agg, c->paylen);
    }
    if (!len) return false;
    if (!do_emit(c, d, frame, len)) return false;
    c->tx_data++;
    return true;
}

static void coll_service(coll_t *c, int retry_rank) {
    refresh_E(c);
    for (int r = 0; r < 4; r++) {
        if (c->E[r] > 0 && (c->E[r] > c->U[r] || c->repeat[r])) {
            if (!send_up(c, r)) goto out;
        }
    }
    if (retry_rank >= 0) {
        for (uint64_t q = c->ackd[retry_rank]; q < c->sent[retry_rank]; q++) {
            if (!send_result(c, retry_rank, q)) goto out;
        }
    }
    for (int d = 0; d < 4; d++) {
        while (c->sent[d] < out_len(c, d)) {
            uint32_t p;
            int src;
            out_map(c, d, c->sent[d], &p, &src);
            slot_t *s = slot_at(c, p);
            if (!s || !slot_complete(c, s)) break;
            if (!send_result(c, d, c->sent[d])) goto out;
            c->sent[d]++;
        }
    }
out:
    retire(c);
}

/* ------------------------------------------------------------------ */
/* Ingress                                                             */
/* ------------------------------------------------------------------ */

static void accept_data(coll_t *c, uint32_t p, int rank, const uint8_t *pay) {
    slot_t *s = &c->slots[p % c->N];
    if (!s->in_use || s->p != p) {
        if (s->in_use) {
            c->slot_overwrites++; /* never observed: window keeps p unique */
            clear_slot(c, s);
        }
        memset(s, 0, sizeof(*s));
        s->in_use = true;
        s->p = p;
    }
    s->mask |= (uint8_t)(1u << rank);
    if (c->prim == EPIC_PRIM_ALLGATHER || c->prim == EPIC_PRIM_BCAST) {
        uint8_t *buf = malloc(c->paylen ? c->paylen : 1);
        if (!buf) abort();
        memcpy(buf, pay, c->paylen);
        free(s->raw[rank]);
        s->raw[rank] = buf;
    } else {
        for (uint32_t j = 0; j < c->D; j++)
            s->agg[j] += be32(pay + 4 * j);
    }
    c->accepted++;
    c->occ++;
    /* advance contiguous received prefix */
    for (int r = 0; r < 4; r++) {
        while (c->R[r] < c->K) {
            slot_t *t = slot_at(c, c->R[r]);
            if (!t || !(t->mask & (1u << r))) break;
            c->R[r]++;
        }
    }
}

static void coll_ingress(coll_t *c, int rank, const uint8_t *frame,
                         size_t length) {
    parsed_t in;
    if (!wire_valid(c, frame, length, &in)) {
        c->invalid_wire++;
        return;
    }
    if (!endpoint_ok(c, rank, frame, &in)) {
        c->invalid_endpoint++;
        return;
    }
    if (!in.is_ack) {
        uint32_t p = (in.psn - c->start) & 0x00ffffffu;
        c->rx_data++;
        if ((uint64_t)p < c->b) {
            c->stale++;
            c->repeat[rank] = true;
        } else if ((uint64_t)p >= (uint64_t)c->b + c->N) {
            c->blocked++;
        } else {
            slot_t *s = &c->slots[p % c->N];
            if (s->in_use && s->p == p && (s->mask & (1u << rank))) {
                c->duplicates++;
                c->repeat[rank] = true;
            } else {
                accept_data(c, p, rank, in.payload);
            }
        }
    } else {
        uint64_t plen = ((in.psn - c->start + 1) & 0x00ffffffu);
        c->rx_ack++;
        if (plen > 0 && plen > c->ackd[rank] && plen <= c->sent[rank])
            c->ackd[rank] = plen;
        else
            c->ack_ignored++;
    }
    coll_service(c, -1);
}

static void coll_retry(coll_t *c, int rank) {
    if (rank >= 0 && rank < 4) c->repeat[rank] = true;
    coll_service(c, rank);
}

/* ------------------------------------------------------------------ */
/* Lifecycle and certificates                                          */
/* ------------------------------------------------------------------ */

static coll_t *coll_open(int primitive, int mode, int root, uint32_t count,
                         uint32_t words, uint32_t capacity, uint32_t start,
                         epic_emit_fn emit, void *user) {
    coll_t *c = calloc(1, sizeof(*c));
    if (!c) return NULL;
    c->prim = primitive;
    c->mode = mode;
    c->root = root;
    c->K = count;
    c->D = words;
    c->N = capacity;
    c->start = start;
    c->paylen = (size_t)words * 4;
    c->emit = emit;
    c->user = user;
    c->slots = calloc(capacity, sizeof(slot_t));
    if (!c->slots) {
        free(c);
        return NULL;
    }
    return c;
}

static void coll_close(coll_t *c) {
    if (!c) return;
    for (uint32_t i = 0; i < c->N; i++) clear_slot(c, &c->slots[i]);
    free(c->slots);
    free(c);
}

static void coll_state(coll_t *c, uint64_t *state) {
    memset(state, 0, 32 * sizeof(*state));
    state[0] = c->b;
    state[1] = c->occ;
    for (int r = 0; r < 4; r++) {
        state[2 + r] = c->R[r];
        state[6 + r] = c->sent[r];
        state[10 + r] = c->ackd[r];
        state[14 + r] = c->U[r];
    }
    uint64_t values[] = {c->rx_data,      c->rx_ack,        c->tx_data,
                         c->tx_ack,       c->accepted,      c->duplicates,
                         c->blocked,      c->stale,         c->invalid_wire,
                         c->invalid_endpoint,               c->ack_ignored,
                         c->failed_sends, c->slot_overwrites};
    memcpy(state + 18, values, sizeof(values));
}

static uint64_t fnv_byte(uint64_t h, uint8_t v) {
    return (h ^ v) * UINT64_C(1099511628211);
}
static uint64_t fnv_u32le(uint64_t h, uint32_t v) {
    for (int i = 0; i < 4; i++) {
        h = fnv_byte(h, (uint8_t)v);
        v >>= 8;
    }
    return h;
}
static uint64_t fnv_u64le(uint64_t h, uint64_t v) {
    for (int i = 0; i < 8; i++) {
        h = fnv_byte(h, (uint8_t)v);
        v >>= 8;
    }
    return h;
}
static uint64_t fnv_bytes(uint64_t h, const uint8_t *p, size_t n) {
    for (size_t i = 0; i < n; i++) h = fnv_byte(h, p[i]);
    return h;
}

static uint64_t coll_digest(coll_t *c) {
    uint64_t h = UINT64_C(14695981039346656037);
    uint64_t top = (uint64_t)c->b + c->N;
    if (top > c->K) top = c->K;
    for (uint64_t p = c->b; p < top; p++) {
        slot_t *s = slot_at(c, p);
        if (!s || s->mask == 0) continue;
        h = fnv_u64le(h, p);
        h = fnv_byte(h, s->mask);
        h = fnv_byte(h, slot_complete(c, s) ? 1 : 0);
        if (c->prim == EPIC_PRIM_ALLGATHER) {
            for (int r = 0; r < 4; r++) {
                h = fnv_byte(h, s->raw[r] ? 1 : 0);
                if (s->raw[r]) h = fnv_bytes(h, s->raw[r], c->paylen);
            }
        } else if (c->prim == EPIC_PRIM_BCAST) {
            if (s->raw[c->root]) h = fnv_bytes(h, s->raw[c->root], c->paylen);
        } else if (c->prim != EPIC_PRIM_BARRIER) {
            for (uint32_t j = 0; j < c->D; j++) h = fnv_u32le(h, s->agg[j]);
        }
    }
    return h;
}

/* ------------------------------------------------------------------ */
/* ABI                                                                 */
/* ------------------------------------------------------------------ */

void *epic_open(int primitive, int mode, int root, uint32_t count,
                uint32_t words, uint32_t capacity, uint32_t start,
                epic_emit_fn emit, void *user) {
    return coll_open(primitive, mode, root, count, words, capacity, start,
                     emit, user);
}
void epic_close(void *context) { coll_close((coll_t *)context); }
int epic_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    coll_ingress((coll_t *)context, rank, frame, length);
    return 0;
}
int epic_flush(void *context) {
    coll_service((coll_t *)context, -1);
    return 0;
}
int epic_retry(void *context, int rank) {
    coll_retry((coll_t *)context, rank);
    return 0;
}
void epic_state(void *context, uint64_t *state) {
    coll_state((coll_t *)context, state);
}
uint64_t epic_digest(void *context) { return coll_digest((coll_t *)context); }
