/* Offline four-port collective collector.
 *
 * Strict implementation of the PROTOCOL.md replay contract: finite CPU packet
 * replay with wire/endpoint validation, bounded retention, cumulative ACKs,
 * transport backpressure and canonical egress construction. All state is
 * in-memory; nothing here touches live I/O.
 */
#define _DEFAULT_SOURCE

#include <arpa/inet.h>

#include "epic_clean.h"
#include "offline_api.h"

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

#define ALLMASK 0x0fu
#define MAX_WORDS (EPIC_MAX_PAYLOAD_BYTES / 4)
#define MAX_FRAME (14 + 20 + 8 + 12 + EPIC_MAX_PAYLOAD_BYTES + 4)

/* ------------------------------------------------------------------ */
/* State                                                               */
/* ------------------------------------------------------------------ */

typedef struct {
    bool in_use;
    uint32_t p;                /* logical input sequence of this slot */
    uint8_t mask;              /* accepted source bitmask */
    uint32_t agg[MAX_WORDS];   /* running sum for aggregate primitives */
    uint8_t *raw[4];           /* raw vectors: gather per source, bcast root */
} slot_t;

typedef struct {
    int prim, mode, root;
    uint32_t K, D, N, start;
    size_t paylen;             /* 4*D */
    slot_t *slots;             /* N entries, indexed by logical p mod N */
    uint64_t b;                /* retired prefix */
    uint64_t occ;              /* occupied slot count */
    uint64_t R[4], E[4], U[4], sent[4], ackd[4];
    bool repeat[4];
    uint64_t rx_data, rx_ack, tx_data, tx_ack;
    uint64_t accepted, duplicates, blocked, stale;
    uint64_t invalid_wire, invalid_endpoint, ack_ignored, failed_sends;
    uint64_t slot_overwrites;
    epic_emit_fn emit;
    void *user;
} coll_t;

/* ------------------------------------------------------------------ */
/* Small helpers                                                       */
/* ------------------------------------------------------------------ */

static uint16_t be16(const uint8_t *p) {
    return (uint16_t)(((uint16_t)p[0] << 8) | p[1]);
}
static uint32_t be32(const uint8_t *p) {
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) |
           ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}
static uint32_t le32(const uint8_t *p) {
    return (uint32_t)p[0] | ((uint32_t)p[1] << 8) | ((uint32_t)p[2] << 16) |
           ((uint32_t)p[3] << 24);
}

static int ordinal_excluding(int d, int s) {
    int o = 0;
    for (int r = 0; r < 4; r++) {
        if (r == d) continue;
        if (r == s) return o;
        o++;
    }
    return -1;
}
static int rank_from_ordinal(int d, int o) {
    for (int r = 0; r < 4; r++) {
